-- Create "rbac_policy_outbox_events" table
CREATE TABLE "rbac_policy_outbox_events" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "event_id" uuid NOT NULL,
  "kind" character varying NOT NULL,
  "reason" character varying NOT NULL,
  "role_id" uuid NULL,
  "user_id" uuid NULL,
  "permission_id" uuid NULL,
  "status" character varying NOT NULL DEFAULT 'pending',
  "attempt_count" bigint NOT NULL DEFAULT 0,
  "next_attempt_at" bigint NOT NULL,
  "last_error" character varying NULL,
  "idempotency_key" character varying NOT NULL,
  "created_at" bigint NOT NULL,
  "updated_at" bigint NOT NULL,
  "delivered_at" bigint NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "rbac_policy_outbox_events_event_id_key" to table: "rbac_policy_outbox_events"
CREATE UNIQUE INDEX "rbac_policy_outbox_events_event_id_key" ON "rbac_policy_outbox_events" ("event_id");
-- Create index "rbac_policy_outbox_events_idempotency_key_key" to table: "rbac_policy_outbox_events"
CREATE UNIQUE INDEX "rbac_policy_outbox_events_idempotency_key_key" ON "rbac_policy_outbox_events" ("idempotency_key");
-- Create index "rbac_policy_outbox_events_revision_key" to table: "rbac_policy_outbox_events"
CREATE UNIQUE INDEX "rbac_policy_outbox_events_revision_key" ON "rbac_policy_outbox_events" ("revision");
-- Create index "rbacpolicyoutboxevent_status_next_attempt_at_revision" to table: "rbac_policy_outbox_events"
CREATE INDEX "rbacpolicyoutboxevent_status_next_attempt_at_revision" ON "rbac_policy_outbox_events" ("status", "next_attempt_at", "revision");
-- Set comment to column: "id" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."id" IS 'RBAC policy outbox 内部ID';
-- Set comment to column: "event_id" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."event_id" IS '稳定 outbox event ID';
-- Set comment to column: "kind" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."kind" IS '事件类型';
-- Set comment to column: "reason" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."reason" IS '触发 policy 变更的稳定原因';
-- Set comment to column: "role_id" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."role_id" IS '相关外部角色ID';
-- Set comment to column: "user_id" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."user_id" IS '相关外部用户ID';
-- Set comment to column: "permission_id" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."permission_id" IS '相关外部权限ID';
-- Set comment to column: "status" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."status" IS '投递状态';
-- Set comment to column: "attempt_count" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."attempt_count" IS '投递尝试次数';
-- Set comment to column: "next_attempt_at" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."next_attempt_at" IS '下次允许尝试的时间戳毫秒';
-- Set comment to column: "last_error" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."last_error" IS '最近一次投递错误';
-- Set comment to column: "idempotency_key" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."idempotency_key" IS '稳定投递幂等键';
-- Set comment to column: "created_at" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."created_at" IS '创建时间戳毫秒';
-- Set comment to column: "updated_at" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."updated_at" IS '更新时间戳毫秒';
-- Set comment to column: "delivered_at" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."delivered_at" IS '投递完成时间戳毫秒';
-- Set comment to column: "revision" on table: "rbac_policy_outbox_events"
COMMENT ON COLUMN "rbac_policy_outbox_events"."revision" IS '关联的 RBAC policy revision';
-- Create "rbac_policy_revisions" table
CREATE TABLE "rbac_policy_revisions" (
  "revision" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "reason" character varying NOT NULL,
  "role_id" uuid NULL,
  "user_id" uuid NULL,
  "permission_id" uuid NULL,
  "created_at" bigint NOT NULL,
  PRIMARY KEY ("revision")
);
-- Set comment to column: "revision" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."revision" IS '单调递增的 RBAC policy revision';
-- Set comment to column: "reason" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."reason" IS '触发 policy 变更的稳定原因';
-- Set comment to column: "role_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."role_id" IS '相关外部角色ID';
-- Set comment to column: "user_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."user_id" IS '相关外部用户ID';
-- Set comment to column: "permission_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."permission_id" IS '相关外部权限ID';
-- Set comment to column: "created_at" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."created_at" IS '创建时间戳毫秒';
